import{r as s}from"./chunks/relatedArticles.CW_ys7fD.js";import{I as i,o,c as r,b6 as l,J as n,k as d}from"./chunks/framework.COUcLbTA.js";const A=JSON.parse('{"title":"아이디어에서 AI 제품까지 - Easy-Vibe 학습 로드맵","description":"AI 프로그래밍을 배우기 위한 전체 로드맵: 제로 베이스에서 풀스택 개발까지. Vibe Coding, Claude Code, Cursor 같은 AI IDE 도구를 익히고, 제품 사고, 풀스택 개발, AI 기능 통합을 배웁니다.","frontmatter":{"title":"아이디어에서 AI 제품까지 - Easy-Vibe 학습 로드맵","description":"AI 프로그래밍을 배우기 위한 전체 로드맵: 제로 베이스에서 풀스택 개발까지. Vibe Coding, Claude Code, Cursor 같은 AI IDE 도구를 익히고, 제품 사고, 풀스택 개발, AI 기능 통합을 배웁니다."},"headers":[],"relativePath":"ko-kr/stage-1/learning-map/index.md","filePath":"ko-kr/stage-1/learning-map/index.md"}'),p={name:"ko-kr/stage-1/learning-map/index.md"},I=Object.assign(p,{setup(c){const a=s["ko-kr/stage-1/learning-map"]??[];return(u,t)=>{const e=i("RelatedArticlesSection");return o(),r("div",null,[t[0]||(t[0]=l('<h1 id="아이디어에서-ai-제품까지" tabindex="-1">아이디어에서 AI 제품까지 <a class="header-anchor" href="#아이디어에서-ai-제품까지" aria-label="Permalink to “아이디어에서 AI 제품까지”">​</a></h1><p>예전에는 소프트웨어를 만들기 위한 문턱이 높았습니다. 프로그래밍을 알아야 했고, 알고리즘도 알아야 했고, 몇 년의 프로젝트 경험도 필요했습니다. 지금은 다릅니다. 아이디어만 있다면 AI가 코드를 작성하도록 도와줄 수 있습니다.</p><p>이것은 거대한 변화입니다. <strong>프로그래밍 언어가 자연어로 변하고 있습니다</strong>.</p><p>대형 언어 모델(LLM)의 등장은 개발을 더 이상 &quot;기술 고수만의 전유물&quot;이 아니라, 누구나 시작할 수 있는 도구로 바꾸었습니다. 예전에는 가장 어려운 것이 &quot;코드를 어떻게 쓰는가&quot;였다면, 지금 가장 어려운 것은 &quot;<strong>무엇을 만들 것인가</strong>&quot;입니다.</p><blockquote><p><strong>Vibe Coding이란 무엇인가요?</strong> 간단히 말하면 &quot;말로 하는 프로그래밍&quot;입니다. Vibe Coding은 직접 코드를 쓰는 대신 AI와 대화하는 방식에 의존해 프로그래밍 프로젝트를 완성하는 것을 뜻합니다.</p></blockquote><p>물론 AI가 코드를 쓰게 하는 것은 첫걸음일 뿐입니다. 정말 사용할 수 있는 제품을 만들려면 다음과 같은 문제도 만나게 됩니다.</p><ul><li>AI가 깨끗하고 유지보수 가능한 코드를 쓰게 하려면 어떻게 해야 할까?</li><li>흩어진 코드 조각을 실행 가능한 애플리케이션으로 어떻게 조립할까?</li><li>애플리케이션을 실제로 배포하고 사람들이 쓰게 하려면 어떻게 해야 할까?</li><li>텍스트 생성, 이미지 인식 같은 AI 기능을 내 제품에 어떻게 넣을까?</li></ul><p>이 질문들은 이 강의 안에서 답을 찾게 됩니다.</p><p>학생이든, 교사든, 의사든, 노동자든, 기술을 전혀 모르는 평범한 사람이든 상관없습니다. 몇 년씩 프로그래밍을 먼저 배울 필요 없이, 2주면 실행되고 시연할 수 있는 제품 프로토타입을 만들 수 있습니다.</p><table tabindex="0"><thead><tr><th>당신의 정체성</th><th>이 강의가 도와줄 수 있는 것</th></tr></thead><tbody><tr><td>학생</td><td>과제, 대회, 창업 프로젝트를 직접 만들고 더 이상 남에게 부탁하지 않기</td></tr><tr><td>직장인</td><td>반복 업무를 자동화하고, 효율을 높이며, 부업까지 개발하기</td></tr><tr><td>제품 관리자 / 디자이너</td><td>아이디어가 종이에 머물지 않고, 상사나 고객에게 보여 줄 Demo를 빠르게 만들기</td></tr><tr><td>창업자 / 중소기업 운영자</td><td>저비용으로 아이디어를 검증하고, 수만 위안을 들여 외주를 맡기지 않아도 MVP 만들기</td></tr><tr><td>교사 / 교육 종사자</td><td>교육 도구, 수업 자료, 자동 문제 출제를 만들어 교육 효율 높이기</td></tr><tr><td>의사 / 변호사 / 전문직</td><td>전문 업무 흐름을 자동화하고 자신만의 효율 도구 만들기</td></tr><tr><td>누구나</td><td>AI로 생활과 업무의 구체적인 문제를 해결하고, 불가능해 보였던 일을 가능하게 만들기</td></tr></tbody></table><p>AI 시대에는 실행력과 아이디어가 언제나 기술보다 더 중요합니다.</p><h2 id="성장-경로-ai를-쓸-줄-아는-사람-에서-ai-제품을-만들-줄-아는-사람-으로" tabindex="-1">성장 경로: &quot;AI를 쓸 줄 아는 사람&quot;에서 &quot;AI 제품을 만들 줄 아는 사람&quot;으로 <a class="header-anchor" href="#성장-경로-ai를-쓸-줄-아는-사람-에서-ai-제품을-만들-줄-아는-사람-으로" aria-label="Permalink to “성장 경로: &quot;AI를 쓸 줄 아는 사람&quot;에서 &quot;AI 제품을 만들 줄 아는 사람&quot;으로”">​</a></h2><div class="stage-intro"><div class="stage-card"><div class="stage-icon">🎮</div><h3>초보자 입문</h3><p class="stage-role">AI 프로그래밍 체험</p><div class="stage-tags"><span>스네이크 미니게임</span><span>제로 베이스 시작</span><span>Vibecoding 첫 경험</span><span>몇 분 만에 생성</span></div></div></div><div class="stage-grid"><div class="stage-card"><div class="stage-icon">🛠️</div><h3>1단계</h3><p class="stage-role">제품 관리자 / 운영</p><div class="stage-tags"><span>AI IDE (Cursor/Claude)</span><span>요구사항 분해 &amp; 프로토타입</span><span>AI 기능 접목</span><span>완성 Demo 개발</span></div></div><div class="stage-card"><div class="stage-icon">💻</div><h3>2단계</h3><p class="stage-role">초중급 개발자 / 독립 개발자</p><div class="stage-tags"><span>Figma에서 코드로</span><span>Supabase 데이터베이스</span><span>Stripe 결제 통합</span><span>Dify 지식베이스</span></div></div><div class="stage-card"><div class="stage-icon">🚀</div><h3>3단계</h3><p class="stage-role">고급 개발자 / 아키텍트</p><div class="stage-tags"><span>Web/미니프로그램/멀티 플랫폼</span><span>MCP 고급 도구</span><span>RAG &amp; LangGraph</span><span>시니어 엔지니어 사고방식</span></div></div></div><p>이 완성된 학습 경로를 통해 당신은 다음을 얻게 됩니다.</p><ul><li><strong>Vibe Coding 개발 능력:</strong> Vibecoding 사고방식과 AI 코딩 도구를 능숙하게 사용해 개발 효율을 몇 배로 높입니다. 더 이상 문법을 억지로 외우는 것이 아니라, AI가 고품질 코드를 생성하도록 이끄는 방법을 배웁니다.</li><li><strong>풀스택 개발 역량:</strong> UI 디자인에서 프론트엔드 구현까지, 데이터베이스 설계에서 API 개발까지, 로컬 개발에서 클라우드 배포까지 현대 Web 애플리케이션의 전체 기술 스택을 익힙니다.</li><li><strong>AI 기능 통합:</strong> 다양한 멀티모달 AI API를 호출하는 법을 배우고, 텍스트, 이미지, 음성 등 AI 기능을 애플리케이션에 매끄럽게 통합하며, RAG 같은 기술로 지능형 제품을 구축합니다.</li><li><strong>제품 사고와 운영 능력:</strong> 사용자 조사에서 요구사항 분해까지, MVP 설계에서 제품 반복 개선까지, 결제 통합에서 사용자 관리까지, 완전한 제품 개발과 운영의 폐쇄 루프를 형성합니다.</li></ul><h1 id="다-배우고-나면-무엇을-할-수-있나요" tabindex="-1">다 배우고 나면 무엇을 할 수 있나요? <a class="header-anchor" href="#다-배우고-나면-무엇을-할-수-있나요" aria-label="Permalink to “다 배우고 나면 무엇을 할 수 있나요?”">​</a></h1><h2 id="_1단계-나의-첫-제품-프로토타입-만들기" tabindex="-1">1단계: 나의 첫 제품 프로토타입 만들기 <a class="header-anchor" href="#_1단계-나의-첫-제품-프로토타입-만들기" aria-label="Permalink to “1단계: 나의 첫 제품 프로토타입 만들기”">​</a></h2><p>이 단계는 프로그래밍 기초가 전혀 없거나, 조금은 알지만 자신감이 부족한 사람에게 적합합니다. 이론 지식을 잔뜩 먼저 배울 필요 없이, 바로 따라 만들면서 AI 도구로 코드를 작성하는 법을 배웁니다.</p><p><strong>배우고 나면 할 수 있는 것</strong>:</p><ul><li>AI 프로그래밍 도구로 웹 애플리케이션 하나를 독립적으로 완성하기</li><li>제품 아이디어를 클릭 가능하고 상호작용 가능한 프로토타입으로 바꾸기</li><li>프로토타입에 AI 기능 추가하기. 예: 텍스트로 이미지 만들기, 지능형 대화</li><li>오류가 났을 때 어떻게 확인하고 해결해야 하는지 알기</li></ul><p>간단히 말하면, &quot;실행되고, 다른 사람에게 시연할 수 있는&quot; 무언가를 만들 수 있게 됩니다.</p><p>먼저 미니게임으로 AI 프로그래밍을 체감하고, AI 프로그래밍 도구가 코드를 작성하고 오류를 고치도록 도와주는 법을 배웁니다. 이어서 간단한 페이지에서 시작해 점차 상호작용 가능한 다중 페이지 애플리케이션을 만들고, 텍스트-이미지 생성, 지능형 대화 같은 AI 기능을 더합니다. 마지막에는 독립적으로 완성 프로젝트를 끝내며, 당신의 아이디어가 실제로 구현될 가능성을 갖게 됩니다.</p><h1 id="왜-프로젝트-기반으로-훈련해야-할까요" tabindex="-1">왜 프로젝트 기반으로 훈련해야 할까요? <a class="header-anchor" href="#왜-프로젝트-기반으로-훈련해야-할까요" aria-label="Permalink to “왜 프로젝트 기반으로 훈련해야 할까요?”">​</a></h1><blockquote><p><strong>현실 세계의 도전</strong></p><p>이유는 사실 간단합니다. 대부분의 학습자가 현재 상태로 바로 직장에 들어가면, 실제 프로젝트와 상사/고객의 &quot;사회적 혹독함&quot; 앞에서 한 걸음도 나아가기 어려울 가능성이 큽니다. 현실 세계에서 더 흔한 장면은 이렇습니다.</p></blockquote><blockquote><p>지도교수 / 상사: 우리는 xxx를 만들려고 해. 목표는 yyy 효과를 내는 거야.</p><p>문서? 준비된 프레임워크? 상세한 요구사항 설명? 많은 경우 존재하지 않습니다.</p></blockquote><p>실제 업무 속 많은 과제는 본질적으로 높은 불확실성 속에서 한 번도 본 적 없는 문제를 해결하는 일입니다. 요구사항은 모호하고, 경계는 계속 변하며, 누구도 정답을 알려 주지 않습니다. 스스로 자료를 찾고, 실험하고, 프로토타입을 만들고, 계속 반복 개선한 끝에 &quot;실행되고, 사용할 수 있고, 배포 가능한&quot; 해결책을 내놓아야 합니다.</p><p>이 강의가 하려는 일은 비교적 안전한 환경에서 미리 한 번 &quot;모의 사회적 혹독함&quot;을 겪게 하는 것입니다.</p><ul><li>어느 정도 난이도가 있어 보이는 프로젝트 과제를 통해 문제를 분해하고, 방안을 설계하고, 스스로 자료를 찾는 연습을 강제합니다.</li><li>지나치게 &quot;따라 하기만 하면 되는&quot; 스캐폴딩과 코드가 아니라, 중대형 코드베이스를 읽고 이해하고 고치는 법을 배우게 합니다.</li><li>아이디어에서 배포까지 이어지는 완전한 폐쇄 루프를 통해 실제 제품이 0에서 1로 만들어지는 전체 과정을 경험하게 합니다.</li></ul><p>단기적으로는 이런 훈련이 꽤 고통스러울 수 있습니다. 하지만 장기적으로는 구직과 커리어 성장에서 경쟁력을 크게 높여 줍니다. 더 큰 일을 감당할 수 있고, 불확실한 환경에서 돌파구를 찾을 수 있으며, AI를 &quot;Demo를 가지고 노는 단계&quot;에 머물게 하지 않고 실제 제품으로 구현할 능력을 갖추게 됩니다.</p><h1 id="질문의-기술-ai-시대의-필수-역량" tabindex="-1">질문의 기술: AI 시대의 필수 역량 <a class="header-anchor" href="#질문의-기술-ai-시대의-필수-역량" aria-label="Permalink to “질문의 기술: AI 시대의 필수 역량”">​</a></h1><p>AI 시대에는 질문도 일종의 &quot;기본기&quot;입니다. 같은 코드, 같은 오류라도 <strong>어떻게 질문하느냐가 AI가 어떤 답을 줄 수 있는지를 거의 결정합니다</strong>. 두루뭉술한 설명으로 끝날지, 아니면 단계별로 실행 가능한 수정 방법을 줄지가 달라집니다.</p><p><strong>좋은 습관을 들이세요</strong>: &quot;AI에게 질문하기&quot;를 일상적인 개발 흐름의 일부로 생각하세요. 이해가 안 되거나 막히는 문제가 생기면 바로 질문합니다.</p><h2 id="왜-이것이-필수-역량인가요" tabindex="-1">왜 이것이 필수 역량인가요? <a class="header-anchor" href="#왜-이것이-필수-역량인가요" aria-label="Permalink to “왜 이것이 필수 역량인가요?”">​</a></h2><ul><li><strong>현실에는 완전한 문서가 드뭅니다</strong>: 더 자주 마주하는 것은 불명확한 요구사항, 반쯤 만들어진 코드, 흩어진 오류 정보입니다.</li><li><strong>AI는 당신 곁의 멘토이자 동료입니다</strong>: 질문을 잘하는 사람은 AI를 &quot;고품질 페어 프로그래밍 파트너&quot;로 만들 수 있습니다.</li><li><strong>능력의 상한은 소통이 결정합니다</strong>: 핵심 정보를 더 잘 제공하고, 출력 형식을 더 잘 제한할수록 답변은 더 쓸모 있어집니다.</li></ul><p><strong>흔한 오해</strong>: &quot;왜 오류가 나나요?&quot;라고 한마디만 물으면 대부분 추측만 잔뜩 받게 됩니다. 맥락을 채워 넣어야 실행 가능한 방안을 얻습니다.</p><h2 id="정보를-ai에게-먹이는-방법-스크린샷-vs-복사-붙여넣기" tabindex="-1">정보를 AI에게 &quot;먹이는&quot; 방법: 스크린샷 vs 복사/붙여넣기 <a class="header-anchor" href="#정보를-ai에게-먹이는-방법-스크린샷-vs-복사-붙여넣기" aria-label="Permalink to “정보를 AI에게 &quot;먹이는&quot; 방법: 스크린샷 vs 복사/붙여넣기”">​</a></h2><p>두 방식 모두 가능하지만 용도가 다릅니다.</p><table tabindex="0"><thead><tr><th>방식</th><th>적합한 상황</th><th>핵심 요구사항</th></tr></thead><tbody><tr><td><strong>복사/붙여넣기</strong></td><td>오류 스택, 로그, 코드, 설정, API 응답</td><td>가능한 한 완전하게. 핵심 키워드 한 줄만 자르지 않기</td></tr><tr><td><strong>스크린샷</strong></td><td>UI 레이아웃 문제, 상호작용 이상, 도구 화면에서 버튼을 찾기 어려운 경우</td><td>전체 화면 캡처 + 중요 영역 표시. 가능하면 짧은 설명 한 문장 추가</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">⚠️ 중요한 전제</p><p><strong>모든 AI가 이미지 입력을 지원하는 것은 아닙니다.</strong> 스크린샷으로 소통하려면 AI가 멀티모달 능력, 즉 이미지를 이해하고 분석할 수 있는 능력을 갖춰야 합니다. 현재 이미지 입력을 지원하는 AI에는 Claude(Anthropic), GPT-4V/GPT-4o(OpenAI), Gemini(Google), 그리고 일부 중국산 대형 모델인 Tongyi Qianwen, Wenxin Yiyan 등이 있습니다.</p><p><strong>사용 중인 AI가 이미지 입력을 지원하지 않는다면</strong> 스크린샷은 인식되지 않습니다. 이때는 복사/붙여넣기로 텍스트를 전달하세요.</p></div><h2 id="ai가-잘-설명하게-만드는-프롬프트-기법" tabindex="-1">AI가 &quot;잘 설명하게&quot; 만드는 프롬프트 기법 <a class="header-anchor" href="#ai가-잘-설명하게-만드는-프롬프트-기법" aria-label="Permalink to “AI가 &quot;잘 설명하게&quot; 만드는 프롬프트 기법”">​</a></h2><p>정답만 필요한 것이 아니라 답을 &quot;배우고&quot; 싶다면, 아래와 같은 지시를 쓰면 설명 품질이 크게 올라갑니다.</p><blockquote><p><strong>학습형 질문 예시</strong></p><ul><li>&quot;먼저 이 개념을 5문장으로 명확하게 설명한 뒤, 제가 제대로 이해했는지 확인할 질문을 몇 개 해 주세요.&quot;</li><li>&quot;이 오류 메시지를 자세히 설명해 주세요. 왜 오류가 나는지 이해가 안 됩니다.&quot;</li></ul></blockquote><h1 id="오래-버텼는데도-해결이-안-됩니다-포기하고-싶어요" tabindex="-1">오래 버텼는데도 해결이 안 됩니다. 포기하고 싶어요 <a class="header-anchor" href="#오래-버텼는데도-해결이-안-됩니다-포기하고-싶어요" aria-label="Permalink to “오래 버텼는데도 해결이 안 됩니다. 포기하고 싶어요”">​</a></h1><p>어쩌면 버티는 방법이 맞지 않았을 수 있습니다. 혼자 어둠 속에서 억지로 버티지 말고, 작성자와 조교들에게 이야기해 보세요. 이미 시도한 방법, 만난 구체적인 막힘, 현재의 심리 상태를 솔직하게 말해 주세요. 많은 경우 방향을 조금만 조정하거나 핵심 지식 하나만 보충해도 계속 앞으로 나아갈 수 있습니다.</p><h1 id="튜토리얼-설계가-합리적이지-않은-것-같아요" tabindex="-1">튜토리얼 설계가 합리적이지 않은 것 같아요 <a class="header-anchor" href="#튜토리얼-설계가-합리적이지-않은-것-같아요" aria-label="Permalink to “튜토리얼 설계가 합리적이지 않은 것 같아요”">​</a></h1><p>언제든 작성자에게 연락하거나 issue를 제출하거나, 그룹/수업에서 직접 피드백해 주세요. 우리는 여러분과 함께 이 튜토리얼을 점점 더 좋게 다듬고 싶습니다. 어디가 명확하지 않은지, 어디의 경험이 좋지 않은지, 어디에서 헛수고를 하게 되었는지 솔직하게 지적해 주세요. 더 실제적이고 구체적인 피드백일수록 뒤에 오는 학습자가 덜 헤매도록 도와줍니다.</p><h1 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to “Reference”">​</a></h1><ul><li><a href="https://nju-projectn.github.io/ics-pa-gitbook/ics2025/" target="_blank" rel="noreferrer">난징대학교 컴퓨터과학기술학과 컴퓨터 시스템 기초 과정 실험</a></li></ul>',49)),n(e,{title:"다음에 무엇을 배울 수 있나요",description:"'AI를 쓸 줄 아는 단계'에서 '제품을 만들 줄 아는 단계'로 계속 앞으로 나아갑니다.",items:d(a)},null,8,["items"])])}}});export{A as __pageData,I as default};
